module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter JR = 6'b001000,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

reg [31:0] res;
reg [31:0] sa, sb;
assign sa = $signed(a);
assign sb = $signed(b);

always @(*) begin
    case (aluc)
        ADD: res = sa + sb;
        ADDU: res = a + b;
        SUB: res = sa - sb;
        SUBU: res = a - b;
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: res = {31{sa < sb}};
        SLTU: res = {31{a < b}};
        SLL: res = a << b;
        SRL: res = a >> b;
        SRA: res = a >>> b;
        SLLV: res = a << (b & 31);
        SRLV: res = a >> (b & 31);
        SRAV: res = a >>> (b & 31);
        default: res = 32'b0;
    endcase
end

assign zero = (res == 32'b0);
assign negative = (res[31]);
assign overflow = ((aluc == SLT || aluc == SLTU) && (sa[31] != sb[31]) && (res[31] != sa[31]));
assign flag = (aluc == SLT || aluc == SLTU) ? (res[0]) : (1'b0);

assign r = res;

endmodule
